package com.bank.toarray;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ToArrayTest {

    @Test
    void toArray_returnsObjectArray() {
        List<String> list = List.of("SAV2001", "CUR3001");
        Object[] arr = list.toArray();
        assertThat(arr).isInstanceOf(Object[].class);
        assertThat(arr).isNotInstanceOf(String[].class);  // NOT String[]!
    }

    @Test
    void toArray_castThrowsCCE() {
        List<String> list = List.of("SAV2001", "CUR3001");
        Object[] arr = list.toArray();
        assertThatThrownBy(() -> {
            String[] strArr = (String[]) arr;  // ClassCastException!
        }).isInstanceOf(ClassCastException.class);
    }

    @Test
    void toArray_typed_returnsStringArray() {
        List<String> list = List.of("SAV2001", "CUR3001");
        String[] arr = list.toArray(new String[0]);
        assertThat(arr).isInstanceOf(String[].class);
        assertThat(arr).containsExactly("SAV2001", "CUR3001");
    }

    @Test
    void toArray_methodReference_java11() {
        List<String> list = List.of("SAV2001", "CUR3001");
        String[] arr = list.toArray(String[]::new);
        assertThat(arr).isInstanceOf(String[].class);
        assertThat(arr).containsExactly("SAV2001", "CUR3001");
    }
}
